            new() { Id = 5, Name = "Prof. Emily Brooks", Title = "Professor of English", Email = "ebrooks@university.edu", Bio = "Prof. Brooks is an expert in American literature and creative writing. She is the author of two novels and a collection of essays on modern literary criticism." },
