using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Full name is required.")]
    [StringLength(100)]
    public string FullName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9\-]+$", ErrorMessage = "Student ID must contain only letters, numbers, and hyphens.")]
    [StringLength(20)]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }

    [EmailAddress(ErrorMessage = "Please enter a valid email address.")]
    [Required(ErrorMessage = "Email is required.")]
    public string Email { get; set; } = string.Empty;

    public string? Comments { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Code = "ENG", Name = "English", Description = "Study of literature, writing, and rhetoric." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Study of past events and civilizations." },
            new() { Id = 6, Code = "BIOL", Name = "Biology", Description = "Study of living organisms and life processes." },
        };

        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Alice Chen", Title = "Professor of Computer Science", Email = "achen@university.edu", Bio = "Dr. Chen specializes in artificial intelligence and machine learning. She has published over 50 papers and holds three patents in natural language processing. She received her Ph.D. from MIT." },
            new() { Id = 2, Name = "Dr. Robert Martinez", Title = "Associate Professor of Computer Science", Email = "rmartinez@university.edu", Bio = "Dr. Martinez focuses on software engineering and distributed systems. Prior to academia, he spent 10 years at leading tech companies building large-scale platforms." },
            new() { Id = 3, Name = "Dr. Sarah Johnson", Title = "Professor of Mathematics", Email = "sjohnson@university.edu", Bio = "Dr. Johnson is a renowned researcher in abstract algebra and topology. She has been awarded the university's Distinguished Teaching Award three times." },
            new() { Id = 4, Name = "Dr. Michael Park", Title = "Associate Professor of Physics", Email = "mpark@university.edu", Bio = "Dr. Park conducts research in quantum mechanics and particle physics. He collaborates with CERN and has contributed to several landmark experiments." },
            new() { Id = 5, Name = "Prof. Emily Brooks", Title = "Professor of English", Email = "ebrooks@university.edu", Bio = "Prof. Brooks is an expert in American literature and creative writing. She is the author of two novels and a collection of essays on modern literary criticism." },
            new() { Id = 6, Name = "Dr. James Wilson", Title = "Professor of History", Email = "jwilson@university.edu", Bio = "Dr. Wilson specializes in European history and the Age of Enlightenment. His book on the French Revolution is widely used in university curricula." },
            new() { Id = 7, Name = "Dr. Linda Nguyen", Title = "Associate Professor of Biology", Email = "lnguyen@university.edu", Bio = "Dr. Nguyen researches molecular biology and genetics. She leads the university's genomics lab and mentors dozens of graduate students." },
            new() { Id = 8, Name = "Dr. David Kim", Title = "Assistant Professor of Mathematics", Email = "dkim@university.edu", Bio = "Dr. Kim works on applied mathematics and statistical modeling. His research applies mathematical models to epidemiology and climate science." },
        };

        _courses = new List<Course>
        {
            // Computer Science
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Computer Science", Description = "An introductory course covering fundamental concepts of programming, data structures, and algorithmic thinking. Students will learn to write programs in Python and understand computational problem-solving.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Location = "Science Hall 201", DepartmentId = 1, InstructorId = 1, IsFeatured = true },
            new() { Id = 2, Code = "CS 201", Title = "Data Structures & Algorithms", Description = "In-depth study of data structures including trees, graphs, hash tables, and heaps. Covers algorithm design techniques such as divide-and-conquer, dynamic programming, and greedy algorithms.", Credits = 4, Schedule = "Tue/Thu 10:30 AM–12:00 PM", Location = "Science Hall 305", DepartmentId = 1, InstructorId = 2 },
            new() { Id = 3, Code = "CS 310", Title = "Artificial Intelligence", Description = "Exploration of AI concepts including search algorithms, knowledge representation, machine learning fundamentals, and neural networks. Includes hands-on projects with real-world datasets.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", Location = "Tech Building 110", DepartmentId = 1, InstructorId = 1, IsFeatured = true },
            new() { Id = 4, Code = "CS 350", Title = "Software Engineering", Description = "Principles of software development including requirements analysis, design patterns, testing methodologies, agile practices, and project management for large-scale applications.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", Location = "Tech Building 215", DepartmentId = 1, InstructorId = 2 },

            // Mathematics
            new() { Id = 5, Code = "MATH 101", Title = "Calculus I", Description = "Introduction to differential calculus covering limits, continuity, derivatives, and applications. Emphasizes both computational skills and conceptual understanding.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Location = "Math Building 101", DepartmentId = 2, InstructorId = 3, IsFeatured = true },
            new() { Id = 6, Code = "MATH 201", Title = "Linear Algebra", Description = "Study of vector spaces, linear transformations, matrices, determinants, eigenvalues, and eigenvectors with applications in science and engineering.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", Location = "Math Building 203", DepartmentId = 2, InstructorId = 3 },
            new() { Id = 7, Code = "MATH 301", Title = "Probability & Statistics", Description = "Introduction to probability theory, random variables, distributions, hypothesis testing, and regression analysis. Applications drawn from natural and social sciences.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", Location = "Math Building 105", DepartmentId = 2, InstructorId = 8 },

            // Physics
            new() { Id = 8, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes laboratory sessions with hands-on experiments. Calculus-based approach suitable for science and engineering majors.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Location = "Physics Lab 100", DepartmentId = 3, InstructorId = 4 },
            new() { Id = 9, Code = "PHYS 250", Title = "Quantum Mechanics", Description = "Introduction to quantum theory covering wave-particle duality, the Schrödinger equation, quantum states, and measurement. Prerequisites: PHYS 101, MATH 201.", Credits = 3, Schedule = "Tue/Thu 2:00–3:20 PM", Location = "Physics Lab 210", DepartmentId = 3, InstructorId = 4, IsFeatured = true },

            // English
            new() { Id = 10, Code = "ENG 101", Title = "Composition & Rhetoric", Description = "Development of academic writing skills including argumentation, research methods, and critical analysis. Students produce multiple essays and a research paper.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Location = "Humanities 120", DepartmentId = 4, InstructorId = 5 },
            new() { Id = 11, Code = "ENG 220", Title = "American Literature", Description = "Survey of American literary works from the colonial period to the present. Explores major authors, movements, and cultural contexts that shaped the national literary tradition.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", Location = "Humanities 205", DepartmentId = 4, InstructorId = 5 },

            // History
            new() { Id = 12, Code = "HIST 101", Title = "World History I", Description = "Survey of world civilizations from antiquity through the Renaissance. Covers political, social, economic, and cultural developments across regions.", Credits = 3, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Location = "Liberal Arts 300", DepartmentId = 5, InstructorId = 6, IsFeatured = true },
            new() { Id = 13, Code = "HIST 305", Title = "The Age of Enlightenment", Description = "In-depth examination of the intellectual, political, and social transformations of 18th-century Europe. Explores key thinkers including Voltaire, Rousseau, and Kant.", Credits = 3, Schedule = "Tue/Thu 3:30–4:50 PM", Location = "Liberal Arts 310", DepartmentId = 5, InstructorId = 6 },

            // Biology
            new() { Id = 14, Code = "BIOL 101", Title = "Introduction to Biology", Description = "Foundational course covering cell biology, genetics, evolution, and ecology. Includes weekly lab sessions with microscopy and experimentation.", Credits = 4, Schedule = "Mon/Wed/Fri 8:00–8:50 AM", Location = "Life Sciences 100", DepartmentId = 6, InstructorId = 7 },
            new() { Id = 15, Code = "BIOL 310", Title = "Molecular Biology & Genetics", Description = "Advanced study of DNA replication, gene expression, regulation, and genomic technologies. Covers CRISPR, sequencing methods, and bioinformatics.", Credits = 4, Schedule = "Tue/Thu 10:00–11:20 AM", Location = "Life Sciences 220", DepartmentId = 6, InstructorId = 7, IsFeatured = true },
        };
    }

    public IReadOnlyList<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public IReadOnlyList<Course> GetCourses() => _courses;

    public IReadOnlyList<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public IReadOnlyList<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public IReadOnlyList<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();

    public Instructor? GetInstructor(int id) => _instructors.FirstOrDefault(i => i.Id == id);

    public Department? GetDepartmentForCourse(int courseId)
    {
        var course = GetCourse(courseId);
        return course is null ? null : GetDepartment(course.DepartmentId);
    }
}

