@page "/"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService Catalog

<PageTitle>University Course Catalog</PageTitle>

<div class="hero-banner mb-4 p-5 rounded-3 text-white bg-primary">
    <h1 class="display-5 fw-bold">University Course Catalog</h1>
    <p class="lead mb-3">Explore our departments and courses for the upcoming semester. Find the right classes to advance your academic journey.</p>
    <a href="/courses" class="btn btn-light btn-lg">Browse All Courses</a>
    <a href="/enroll" class="btn btn-outline-light btn-lg ms-2">Enroll Now</a>
</div>

<section class="mb-5">
    <h2 class="mb-3">Featured Courses</h2>
    <div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-4">
        @foreach (var course in featuredCourses)
        {
            var dept = Catalog.GetDepartmentForCourse(course.Id);
            <div class="col">
                <div class="card h-100 shadow-sm">
                    <div class="card-body">
                        <span class="badge bg-secondary mb-2">@dept?.Code</span>
                        <h5 class="card-title">@course.Code — @course.Title</h5>
                        <p class="card-text text-muted">@course.Credits credits · @course.Schedule</p>
                        <p class="card-text">@Truncate(course.Description, 120)</p>
                    </div>
                    <div class="card-footer bg-transparent">
                        <a href="/courses/@course.Id" class="btn btn-outline-primary btn-sm">View Details</a>
                    </div>
                </div>
            </div>
        }
    </div>
</section>

<section>
    <h2 class="mb-3">Departments</h2>
    <div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-3">
        @foreach (var dept in departments)
        {
            var courseCount = Catalog.GetCoursesByDepartment(dept.Id).Count;
            <div class="col">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@dept.Name</h5>
                        <p class="card-text">@dept.Description</p>
                        <p class="text-muted mb-0">@courseCount course(s) available</p>
                    </div>
                    <div class="card-footer bg-transparent">
                        <a href="/courses?departmentId=@dept.Id" class="btn btn-outline-secondary btn-sm">View Courses</a>
                    </div>
                </div>
            </div>
        }
    </div>
</section>

@code {
    private IReadOnlyList<Course> featuredCourses = [];
    private IReadOnlyList<Department> departments = [];

    protected override void OnInitialized()
    {
        featuredCourses = Catalog.GetFeaturedCourses();
        departments = Catalog.GetDepartments();
    }

    private static string Truncate(string text, int maxLength) =>
        text.Length <= maxLength ? text : text[..maxLength] + "…";
}

