@page "/courses"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService Catalog

<PageTitle>Courses — University Course Catalog</PageTitle>

<h1 class="mb-4">Course Catalog</h1>

<form method="get" action="/courses" class="row g-3 mb-4">
    <div class="col-md-6">
        <label for="search" class="form-label">Search courses</label>
        <input type="text" class="form-control" id="search" name="search" value="@Search" placeholder="Search by title, code, or keyword…" />
    </div>
    <div class="col-md-4">
        <label for="departmentId" class="form-label">Department</label>
        <select class="form-select" id="departmentId" name="departmentId">
            <option value="">All Departments</option>
            @foreach (var dept in departments)
            {
                if (dept.Id == DepartmentId)
                {
                    <option value="@dept.Id" selected>@dept.Name</option>
                }
                else
                {
                    <option value="@dept.Id">@dept.Name</option>
                }
            }
        </select>
    </div>
    <div class="col-md-2 d-flex align-items-end">
        <button type="submit" class="btn btn-primary w-100">Filter</button>
    </div>
</form>

@if (selectedDept is not null)
{
    <div class="alert alert-info py-2">
        Showing courses in <strong>@selectedDept.Name</strong>.
        <a href="/courses" class="ms-2">Clear filter</a>
    </div>
}

@if (courses.Count == 0)
{
    <div class="alert alert-warning">No courses match your search criteria.</div>
}
else
{
    <p class="text-muted mb-3">Showing @courses.Count course(s)</p>

    <div class="table-responsive">
        <table class="table table-hover align-middle">
            <thead class="table-light">
                <tr>
                    <th>Code</th>
                    <th>Title</th>
                    <th>Department</th>
                    <th>Credits</th>
                    <th>Schedule</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var course in courses)
                {
                    var dept = Catalog.GetDepartmentForCourse(course.Id);
                    <tr>
                        <td><strong>@course.Code</strong></td>
                        <td>@course.Title</td>
                        <td>@dept?.Name</td>
                        <td>@course.Credits</td>
                        <td>@course.Schedule</td>
                        <td><a href="/courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    [SupplyParameterFromQuery] public string? Search { get; set; }
    [SupplyParameterFromQuery] public int? DepartmentId { get; set; }

    private IReadOnlyList<Department> departments = [];
    private IReadOnlyList<Course> courses = [];
    private Department? selectedDept;

    protected override void OnInitialized()
    {
        departments = Catalog.GetDepartments();
        courses = Catalog.SearchCourses(Search, DepartmentId);
        if (DepartmentId.HasValue)
        {
            selectedDept = Catalog.GetDepartment(DepartmentId.Value);
        }
    }
}

@page "/courses/{Id:int}"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService Catalog

@if (course is null)
{
    <PageTitle>Course Not Found</PageTitle>
    <h1>Course Not Found</h1>
    <p>The requested course does not exist. <a href="/courses">Browse all courses</a>.</p>
}
else
{
    <PageTitle>@course.Code @course.Title — University Course Catalog</PageTitle>

    <nav aria-label="breadcrumb" class="mb-3">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="/courses">Courses</a></li>
            <li class="breadcrumb-item"><a href="/courses?departmentId=@department?.Id">@department?.Name</a></li>
            <li class="breadcrumb-item active" aria-current="page">@course.Code</li>
        </ol>
    </nav>

    <div class="row">
        <div class="col-lg-8">
            <h1 class="mb-1">@course.Code — @course.Title</h1>
            <p class="text-muted mb-4">@department?.Name Department</p>

            <div class="card mb-4">
                <div class="card-body">
                    <h5 class="card-title">Course Description</h5>
                    <p>@course.Description</p>
                </div>
            </div>

            @if (instructor is not null)
            {
                <div class="card mb-4">
                    <div class="card-body">
                        <h5 class="card-title">Instructor</h5>
                        <h6>@instructor.Name</h6>
                        <p class="text-muted mb-2">@instructor.Title · <a href="mailto:@instructor.Email">@instructor.Email</a></p>
                        <p class="mb-0">@instructor.Bio</p>
                    </div>
                </div>
            }
        </div>

        <div class="col-lg-4">
            <div class="card mb-4">
                <div class="card-header fw-bold">Course Details</div>
                <ul class="list-group list-group-flush">
                    <li class="list-group-item"><strong>Code:</strong> @course.Code</li>
                    <li class="list-group-item"><strong>Credits:</strong> @course.Credits</li>
                    <li class="list-group-item"><strong>Schedule:</strong> @course.Schedule</li>
                    <li class="list-group-item"><strong>Location:</strong> @course.Location</li>
                </ul>
            </div>

            <a href="/enroll?courseId=@course.Id" class="btn btn-primary w-100 mb-3">Request Enrollment</a>
            <a href="/courses" class="btn btn-outline-secondary w-100">Back to Catalog</a>
        </div>
    </div>
}

@code {
    [Parameter] public int Id { get; set; }

    private Course? course;
    private Department? department;
    private Instructor? instructor;

    protected override void OnInitialized()
    {
        course = Catalog.GetCourse(Id);
        if (course is not null)
        {
            department = Catalog.GetDepartment(course.DepartmentId);
            instructor = Catalog.GetInstructor(course.InstructorId);
        }
    }
}

@page "/enroll"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService Catalog

<PageTitle>Enrollment Request — University Course Catalog</PageTitle>

<h1 class="mb-4">Enrollment Request</h1>
<p class="text-muted mb-4">Fill out the form below to request enrollment in a course. You will receive a confirmation once your request is processed.</p>

<div class="row">
    <div class="col-lg-8">
        <EditForm method="post" Model="Model" OnValidSubmit="HandleSubmit" FormName="enrollment" Enhance>
            <DataAnnotationsValidator />
            <ValidationSummary class="text-danger mb-3" />

            <div class="mb-3">
                <label for="fullName" class="form-label">Full Name <span class="text-danger">*</span></label>
                <InputText id="fullName" class="form-control" @bind-Value="Model.FullName" />
                <ValidationMessage For="() => Model.FullName" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="studentId" class="form-label">Student ID <span class="text-danger">*</span></label>
                <InputText id="studentId" class="form-control" @bind-Value="Model.StudentId" placeholder="e.g. STU-12345" />
                <ValidationMessage For="() => Model.StudentId" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="email" class="form-label">Email Address <span class="text-danger">*</span></label>
                <InputText id="email" class="form-control" type="email" @bind-Value="Model.Email" />
                <ValidationMessage For="() => Model.Email" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="courseId" class="form-label">Course <span class="text-danger">*</span></label>
                <InputSelect id="courseId" class="form-select" @bind-Value="Model.CourseId">
                    <option value="0">— Select a course —</option>
                    @foreach (var course in allCourses)
                    {
                        <option value="@course.Id">@course.Code — @course.Title (@course.Credits cr)</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.CourseId" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="comments" class="form-label">Comments (optional)</label>
                <InputTextArea id="comments" class="form-control" rows="3" @bind-Value="Model.Comments" />
            </div>

            <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
            <a href="/courses" class="btn btn-outline-secondary ms-2">Cancel</a>
        </EditForm>
    </div>
</div>

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private IReadOnlyList<Course> allCourses = [];

    protected override void OnInitialized()
    {
        allCourses = Catalog.GetCourses();

        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        // In a real application, this would persist the enrollment request.
        submitted = true;
    }

    private bool submitted;
}

@if (submitted)
{
    var selectedCourse = Catalog.GetCourse(Model.CourseId);
    <div class="mt-4 alert alert-success">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>Thank you, <strong>@Model.FullName</strong>. Your enrollment request for
            <strong>@selectedCourse?.Code — @selectedCourse?.Title</strong> has been received.</p>
        <p class="mb-0">A confirmation will be sent to <strong>@Model.Email</strong>. Your student ID on file: <strong>@Model.StudentId</strong>.</p>
        <hr />
        <a href="/courses" class="btn btn-outline-success btn-sm">Browse More Courses</a>
        <a href="/enroll" class="btn btn-outline-secondary btn-sm ms-2">Submit Another Request</a>
    </div>
}

